-- (가)
SELECT COUNT(*) FROM 주문 WHERE 주문가격 <> 1000 OR 주문가격 IS NULL;
-- (나)
SELECT COUNT(*) FROM 주문 WHERE NOT (주문가격 = 1000);
-- (다)
SELECT COUNT(*) FROM 주문
 WHERE 주문가격 NOT IN (SELECT 주문가격 FROM 주문 WHERE 매매구분 = '매도');

SELECT 종목명
  FROM 종목
 ORDER BY 시장구분 DESC, PER;

SELECT O.주문번호, G.등급
  FROM 주문 O, 수수료등급 G
 WHERE O.주문금액 BETWEEN G.하한금액 AND G.상한금액;

-- (가)
SELECT * FROM 주문
 WHERE 주문수량 > ALL (SELECT 주문수량 FROM 주문 WHERE 종목코드 = '999999');
-- (나)
SELECT * FROM 주문
 WHERE 주문수량 > ANY (SELECT 주문수량 FROM 주문 WHERE 종목코드 = '999999');
-- (다)
SELECT * FROM 주문
 WHERE 주문수량 > ALL (SELECT 주문수량 FROM 주문 WHERE 매매구분 = '매도');

-- (가)
SELECT * FROM (SELECT * FROM 거래순위 ORDER BY 거래량 DESC) WHERE ROWNUM <= 3;
-- (나)
SELECT * FROM (SELECT 종목, RANK() OVER (ORDER BY 거래량 DESC) R FROM 거래순위) WHERE R <= 3;
-- (다)
SELECT * FROM (SELECT 종목, DENSE_RANK() OVER (ORDER BY 거래량 DESC) R FROM 거래순위) WHERE R <= 3;
-- (라)
SELECT * FROM 거래순위 ORDER BY 거래량 DESC FETCH FIRST 2 ROWS WITH TIES;

-- (가)
SELECT * FROM 체결
 PIVOT (SUM(수량) FOR 매매구분 IN ('매수' AS 매수, '매도' AS 매도));
-- (나)
SELECT * FROM (SELECT 계좌번호, 매매구분, 수량 FROM 체결)
 PIVOT (SUM(수량) FOR 매매구분 IN ('매수' AS 매수, '매도' AS 매도));

INSERT INTO 관심종목 VALUES ('A');
SAVEPOINT SP1;
DELETE FROM 관심종목 WHERE 종목코드 = '005930';   -- 1건 삭제
SAVEPOINT SP2;
UPDATE 관심종목 SET 종목코드 = 'Z' WHERE 종목코드 = 'A';
ROLLBACK TO SP1;
INSERT INTO 관심종목 VALUES ('B');
CREATE TABLE 관심종목_백업 (종목코드 VARCHAR2(12));
INSERT INTO 관심종목 VALUES ('C');
ROLLBACK;
SELECT COUNT(*) FROM 관심종목;

UPDATE 계좌
   SET 예수금 = 예수금 - 1000000
 WHERE 계좌번호 = 'A1001';
COMMIT;

CREATE INDEX 주문_X01 ON 주문 (주문유형, 주문일자);
CREATE UNIQUE INDEX 체결_PK ON 체결 (주문번호, 체결순번);

(가) SELECT * FROM 주문 WHERE 주문일자 = '20261020';
(나) SELECT COUNT(*) FROM 주문;
